SELECT
pt.*,
a.area_name AS area_name,
os.name AS operation_status_name,
u.user_name AS manager_name,
IFNULL(GROUP_CONCAT(DISTINCT u2.user_name), '') AS cleaners_name_str
FROM public_toilet pt
LEFT JOIN sys_area a ON pt.area_code = a.area_code AND a.deleted = 0
LEFT JOIN sys_operation_status os ON pt.operation_status_id = os.sys_operation_status_id AND os.deleted = 0
LEFT JOIN sys_user u ON pt.manager_id = u.user_id AND u.deleted = 0
LEFT JOIN sys_user u2 ON FIND_IN_SET(
u2.user_id,
REPLACE(REPLACE(REPLACE(REPLACE(pt.cleaner_ids, '[', ''), ']', ''), '"', ''), ' ', '')
) AND u2.deleted = 0
WHERE pt.deleted = 0



    AND pt.toilet_id = #{reqVO.toiletId}


    AND pt.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND pt.location LIKE CONCAT('%', #{reqVO.location}, '%')


    AND pt.area_code = #{reqVO.areaCode}


    AND pt.open_hours LIKE CONCAT('%', #{reqVO.openHours}, '%')




    AND pt.stall_count BETWEEN #{reqVO.stallCount[0]} AND #{reqVO.stallCount[1]}




    AND pt.operation_status_id = #{reqVO.operationStatusId}




    AND pt.manager_id = #{reqVO.managerId}




    AND pt.cleaner_ids LIKE CONCAT('%', #{reqVO.cleanerIds}, '%')




    AND pt.cleaning_rate BETWEEN #{reqVO.cleaningRate[0]} AND #{reqVO.cleaningRate[1]}




    AND pt.complaint_rate BETWEEN #{reqVO.complaintRate[0]} AND #{reqVO.complaintRate[1]}




    AND pt.warning_count >= #{reqVO.warningCount}




    AND pt.facility_rate BETWEEN #{reqVO.facilityRate[0]} AND #{reqVO.facilityRate[1]}




    AND pt.cleaning_frequency LIKE CONCAT('%', #{reqVO.cleaningFrequency}, '%')




    AND pt.consumable_threshold >= #{reqVO.consumableThreshold}




    AND pt.consumable_gap > 0




    AND pt.last_supply_time BETWEEN #{reqVO.lastSupplyTime[0]} AND #{reqVO.lastSupplyTime[1]}




    AND pt.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}




    AND pt.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}


GROUP BY pt.id, a.area_name, os.name, u.user_name
ORDER BY pt.id DESC
LIMIT #{reqVO.offset}, #{reqVO.limit}

SELECT COUNT(DISTINCT pt.id)
FROM public_toilet pt
LEFT JOIN sys_area a ON pt.area_code = a.area_code AND a.deleted = 0
LEFT JOIN sys_operation_status os ON pt.operation_status_id = os.sys_operation_status_id AND os.deleted = 0
LEFT JOIN sys_user u ON pt.manager_id = u.user_id AND u.deleted = 0
WHERE pt.deleted = 0



